SubProceso VerTotal()
  Escribir total;
FinSubProceso

Proceso Principal
  Definir total Como Entero <- 10;
  VerTotal();
FinProceso

Proceso FueraAmbito
  Definir n Como Entero <- 3;
  Si n > 0 Entonces
    Definir doble Como Entero <- n * 2;
    Escribir doble;
  FinSi
  Escribir doble;
FinProceso

Proceso Ambitos
  Definir x Como Entero <- 1;
  Si x > 0 Entonces
    Definir x Como Entero <- 2;
    Escribir "dentro: ", x;
  FinSi
  Escribir "fuera: ", x;
FinProceso
